from django.test import SimpleTestCase


class ClassOnlyMethodTests(SimpleTestCase):
    """Tests for the classonlymethod class."""

    def test_classonlymethod_available_on_class(self):
        """Test that classonlymethod is available on the class."""
        from django.utils.decorators import classonlymethod

        class TestClass:
            @classmethod
            def normal_method(cls):
                return "normal"

            @classonlymethod
            def restricted_method(cls):
                return "restricted"

        # Should be accessible on the class
        result = TestClass.restricted_method()
        self.assertEqual(result, "restricted")

    def test_classonlymethod_raises_on_instance_access(self):
        """Test that accessing classonlymethod on instance raises AttributeError."""
        from django.utils.decorators import classonlymethod

        class TestClass:
            @classonlymethod
            def restricted_method(cls):
                return "restricted"

        obj = TestClass()
        with self.assertRaises(AttributeError) as ctx:
            obj.restricted_method()
        self.assertIn("available only on the class", str(ctx.exception))


class UpdateMethodWrapperTests(SimpleTestCase):
