                       hasattr(dummy_wrapper, '__wrapped__'))


class MultiDecorateTests(SimpleTestCase):
    """Tests for _multi_decorate function."""

    def test_multi_decorate_single_decorator(self):
        """Test decorating with a single decorator."""
        from django.utils.decorators import _multi_decorate

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return f"decorated({func(*args, **kwargs)})"
            return wrapper

        class TestClass:
            def method(self):
                return "original"

        obj = TestClass()
        decorated = _multi_decorate(my_decorator, TestClass.method)
        result = decorated(obj)
        self.assertEqual(result, "decorated(original)")

    def test_multi_decorate_multiple_decorators(self):
        """Test decorating with multiple decorators."""
        from django.utils.decorators import _multi_decorate

        def decorator1(func):
            def wrapper(*args, **kwargs):
                return f"dec1({func(*args, **kwargs)})"
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                return f"dec2({func(*args, **kwargs)})"
            return wrapper

        class TestClass:
            def method(self):
                return "original"

        obj = TestClass()
        decorated = _multi_decorate([decorator1, decorator2], TestClass.method)
        result = decorated(obj)
        # Order should be preserved - decorator2 applied first, then decorator1
        self.assertEqual(result, "dec1(dec2(original))")

    def test_multi_decorate_with_args_kwargs(self):
        """Test that args and kwargs are passed through correctly."""
        from django.utils.decorators import _multi_decorate

        def capture_decorator(func):
            captured_args = []
            captured_kwargs = {}
            def wrapper(*args, **kwargs):
                captured_args.extend(args)
                captured_kwargs.update(kwargs)
                return func(*args, **kwargs)
            wrapper.captured_args = captured_args
            wrapper.captured_kwargs = captured_kwargs
            return wrapper

        class TestClass:
            def method(self, x, y, z=None):
                return f"x={x}, y={y}, z={z}"

        obj = TestClass()
        decorated = _multi_decorate(capture_decorator, TestClass.method)
        result = decorated(obj, 1, 2, z=3)
        self.assertEqual(result, "x=1, y=2, z=3")


class MethodDecoratorTests(SimpleTestCase):
    """Tests for method_decorator function."""

    def test_method_decorator_on_function(self):
        """Test method_decorator applied to a function."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return f"decorated({func(*args, **kwargs)})"
            return wrapper

        def my_function(x):
            return f"value_{x}"

        decorated = method_decorator(my_decorator)(my_function)
        result = decorated(5)
        self.assertEqual(result, "decorated(value_5)")

    def test_method_decorator_on_class_method(self):
        """Test method_decorator applied to a class method."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return f"decorated({func(*args, **kwargs)})"
            return wrapper

        @method_decorator(my_decorator, name='greet')
        class Greeter:
            def greet(self, name):
                return f"Hello, {name}!"

        greeter = Greeter()
        result = greeter.greet("World")
        self.assertEqual(result, "decorated(Hello, World!)")

    def test_method_decorator_missing_name_parameter(self):
        """Test error when name parameter is missing for class decoration."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class TestClass:
            def method(self):
                pass

        # Should raise ValueError because name is not provided
        with self.assertRaises(ValueError) as ctx:
            method_decorator(my_decorator)(TestClass)
        self.assertIn("must be the name of a method", str(ctx.exception))

    def test_method_decorator_non_callable_attribute(self):
        """Test error when decorating non-callable attribute."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class TestClass:
            attr = "not callable"

        # Should raise TypeError because attr is not callable
        with self.assertRaises(TypeError) as ctx:
            method_decorator(my_decorator, name='attr')(TestClass)
        self.assertIn("isn't a callable attribute", str(ctx.exception))

    def test_method_decorator_preserves_attributes(self):
        """Test that method_decorator preserves function attributes."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.custom_attr = "custom_value"
            return wrapper

        @method_decorator(my_decorator, name='test_method')
        class TestClass:
            def test_method(self):
                return "result"

        self.assertTrue(hasattr(TestClass.test_method, 'custom_attr') or
                       hasattr(TestClass.test_method, '__wrapped__'))


