    def test_make_middleware_decorator_template_response_with_process_response(self):
        """Test template response with render and process_response."""
        from django.utils.decorators import make_middleware_decorator

        class TemplateResponse:
            def __init__(self):
                self.rendered = False
                self.callbacks = []

            def render(self):
                self.rendered = True
                # Call all registered callbacks and use their return value if any
                for cb in self.callbacks:
                    result = cb(self)
                    if result is not None:
                        return result
                return "rendered_content"

            def add_post_render_callback(self, callback):
                self.callbacks.append(callback)

        class ProcessResponseMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_response(self, request, response):
                return "processed_via_callback"

        factory = make_middleware_decorator(ProcessResponseMiddleware)
        decorator = factory()

        def view_func(request):
            return TemplateResponse()

        wrapped = decorator(view_func)
        response = wrapped(None)
        # Render the response to trigger callbacks
        rendered = response.render()
        # Should call process_response via callback after render
        self.assertEqual(rendered, "processed_via_callback")

    def test_make_middleware_decorator_template_response_with_process_template_response(self):
        """Test template response with both process_template_response and process_response."""
        from django.utils.decorators import make_middleware_decorator

        class TemplateResponse:
            def __init__(self):
                self.rendered = False
                self.callbacks = []

            def render(self):
                self.rendered = True
                # Call all registered callbacks and use their return value if any
                for cb in self.callbacks:
                    result = cb(self)
                    if result is not None:
                        return result
                return "rendered_content"

            def add_post_render_callback(self, callback):
                self.callbacks.append(callback)

        class FullMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

            def process_template_response(self, request, response):
                # Return a new TemplateResponse that will be processed further
                new_response = TemplateResponse()
                return new_response

            def process_response(self, request, response):
                return "response_processed"

        factory = make_middleware_decorator(FullMiddleware)
        decorator = factory()

        def view_func(request):
            return TemplateResponse()

        wrapped = decorator(view_func)
        response = wrapped(None)
        # Render the response to trigger callbacks
        rendered = response.render()
        # Should call process_response via callback after render
        self.assertEqual(rendered, "response_processed")

