class EdgeCasesTests(SimpleTestCase):
    """Tests for edge cases and boundary conditions."""

    def test_method_decorator_empty_name_raises(self):
        """Test that empty name raises ValueError for class decoration."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        class TestClass:
            def method(self):
                pass

        # Empty string for name should raise ValueError
        with self.assertRaises(ValueError):
            method_decorator(my_decorator, name='')(TestClass)

    def test_multi_decorate_empty_iterable(self):
        """Test behavior with empty iterable of decorators."""
        from django.utils.decorators import _multi_decorate

        class TestClass:
            def method(self):
                return "original"

        obj = TestClass()
        # Empty list should just return original method
        decorated = _multi_decorate([], TestClass.method)
        result = decorated(obj)
        self.assertEqual(result, "original")

    def test_decorator_chain_order(self):
        """Test that decorator chain order is preserved."""
        from django.utils.decorators import _multi_decorate

        def dec_n(n):
            def decorator(func):
                def wrapper(*args, **kwargs):
                    return f"{n}({func(*args, **kwargs)})"
                return wrapper
            return decorator

        class TestClass:
            def method(self):
                return "base"

        obj = TestClass()
        decorated = _multi_decorate([dec_n(1), dec_n(2), dec_n(3)], TestClass.method)
        result = decorated(obj)
        # Order should be: 1(2(3(base)))
        self.assertEqual(result, "1(2(3(base)))")

    def test_method_decorator_return_type(self):
        """Test that method_decorator returns the modified class."""
        from django.utils.decorators import method_decorator

        def my_decorator(func):
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            return wrapper

        @method_decorator(my_decorator, name='test')
        class TestClass:
            def test(self):
                return "result"

        self.assertIsInstance(TestClass, type)
        self.assertTrue(hasattr(TestClass, 'test'))

    def test_make_middleware_decorator_wraps_view_func(self):
        """Test that the wrapped view preserves view_func attributes."""
        from django.utils.decorators import make_middleware_decorator

        class DummyMiddleware:
            def __init__(self, view_func):
                self.view_func = view_func

        factory = make_middleware_decorator(DummyMiddleware)
        decorator = factory()

        def my_view(request):
            """My view docstring."""
            return "response"

        my_view.custom_attr = "custom_value"
        wrapped = decorator(my_view)

        # Should preserve __name__ and __doc__ via wraps
        self.assertEqual(wrapped.__name__, 'my_view')
        self.assertEqual(wrapped.__doc__, 'My view docstring.')

