class TestPROTECT(SimpleTestCase):
    def test_protect_raises_protected_error(self):
        from django.db.models.deletion import PROTECT, ProtectedError

        class MockCollector:
            pass

        class MockRemoteField:
            model = type('MockModel', (), {'__name__': 'MockModel'})

        class MockField:
            remote_field = MockRemoteField()
            name = 'test_field'

        class MockObj:
            __class__ = type('MockObjClass', (), {})

        mock_collector = MockCollector()
        mock_field = MockField()
        mock_objs = [MockObj()]
        mock_using = 'default'

        with self.assertRaises(ProtectedError) as ctx:
            PROTECT(mock_collector, mock_field, mock_objs, mock_using)

        self.assertIn("MockModel", str(ctx.exception))
        self.assertIn("test_field", str(ctx.exception))


