        pre_save_called = []
        post_save_called = []

        def pre_save_handler(sender, instance, **kwargs):
            pre_save_called.append(instance)

        def post_save_handler(sender, instance, created, **kwargs):
            post_save_called.append((instance, created))

        pre_save.connect(pre_save_handler, sender=TestModel)
        post_save.connect(post_save_handler, sender=TestModel)

        try:
            obj = TestModel(name="Test")
            # Mock save_base to avoid actual DB operations
            with mock.patch.object(TestModel, '_save_table', return_value=False):
                obj.save_base()
        finally:
            pre_save.disconnect(pre_save_handler, sender=TestModel)
            post_save.disconnect(post_save_handler, sender=TestModel)

        self.assertEqual(len(pre_save_called), 1)
        self.assertEqual(len(post_save_called), 1)


