class ModelBaseTests(SimpleTestCase):
    """Tests for the ModelBase metaclass."""

    def test_subclass_exception(self):
        from django.db.models.base import subclass_exception

        class TestClass:
            __qualname__ = 'TestClass'

        exc = subclass_exception('MyException', (Exception,), 'test_module', TestClass)
        self.assertEqual(exc.__module__, 'test_module')
        self.assertEqual(exc.__qualname__, 'TestClass.MyException')
        self.assertTrue(issubclass(exc, Exception))

    def test_has_contribute_to_class(self):
        from django.db.models.base import _has_contribute_to_class

        class WithMethod:
            def contribute_to_class(self, cls, name):
                pass

        class WithoutMethod:
            pass

        instance = WithMethod()
        self.assertTrue(_has_contribute_to_class(instance))
        self.assertFalse(_has_contribute_to_class(WithoutMethod))
        self.assertFalse(_has_contribute_to_class("string"))


