class FunctionTests(SimpleTestCase):
    def test_basic_join(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], ", ")
        self.assertEqual(result, "a, b, c")

    def test_join_with_empty_separator(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], "")
        self.assertEqual(result, "abc")

    def test_join_with_special_chars(self):
        from django.template.defaultfilters import join
        result = join(["a&b", "c<d"], " | ")
        self.assertEqual(result, "a&amp;b | c&lt;d")

    def test_join_with_numbers(self):
        from django.template.defaultfilters import join
        result = join([1, 2, 3], "-")
        self.assertEqual(result, "1-2-3")

    def test_join_with_mixed_types(self):
        from django.template.defaultfilters import join
        result = join([1, "two", 3.0], " ")
        self.assertEqual(result, "1 two 3.0")

    def test_join_empty_list(self):
        from django.template.defaultfilters import join
        result = join([], ", ")
        self.assertEqual(result, "")

    def test_join_single_item(self):
        from django.template.defaultfilters import join
        result = join(["only"], ", ")
        self.assertEqual(result, "only")

    def test_join_with_none_values(self):
        from django.template.defaultfilters import join
        result = join([None, "test", None], "-")
        self.assertEqual(result, "None-test-None")

    def test_join_with_boolean_values(self):
        from django.template.defaultfilters import join
        # Boolean values get converted to strings with autoescape=True
        result = join([True, False, True], " & ", autoescape=True)
        self.assertEqual(result, "True &amp; False &amp; True")

    def test_join_with_autoescape_true(self):
        from django.template.defaultfilters import join
        result = join(["a&b", "c<d"], " | ", autoescape=True)
        self.assertEqual(result, "a&amp;b | c&lt;d")

    def test_join_with_autoescape_false(self):
        from django.template.defaultfilters import join
        result = join(["a&b", "c<d"], " | ", autoescape=False)
        self.assertEqual(result, "a&b | c<d")

    def test_join_with_safestring_input(self):
        from django.template.defaultfilters import join
        safe_value = mark_safe("safe & content")
        result = join([safe_value, "normal"], " | ")
        self.assertTrue(hasattr(result, '__html__'))

    def test_join_with_non_iterable_arg(self):
        from django.template.defaultfilters import join
        # When arg is not a string, it gets converted to string and used as separator
        result = join(["a", "b"], 123)
        self.assertEqual(result, "a123b")

    def test_join_with_tuple_input(self):
        from django.template.defaultfilters import join
        result = join(("a", "b", "c"), ", ")
        self.assertEqual(result, "a, b, c")

    def test_join_with_generator_input(self):
        from django.template.defaultfilters import join
        gen = (x for x in ["a", "b", "c"])
        result = join(gen, ", ")
        self.assertEqual(result, "a, b, c")

    def test_join_with_whitespace_separator(self):
        from django.template.defaultfilters import join
        result = join(["hello", "world"], " ")
        self.assertEqual(result, "hello world")

    def test_join_with_newline_separator(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], "\n")
        self.assertEqual(result, "a\nb\nc")

    def test_join_with_tab_separator(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], "\t")
        self.assertEqual(result, "a\tb\tc")

    def test_join_with_unicode_separator(self):
        from django.template.defaultfilters import join
        result = join(["a", "b", "c"], " → ")
        self.assertEqual(result, "a → b → c")

    def test_join_with_long_list(self):
        from django.template.defaultfilters import join
        long_list = list(range(100))
        result = join(long_list, ", ")
        expected = ", ".join(str(x) for x in range(100))
        self.assertEqual(result, expected)

