from django.test import SimpleTestCase


class TestSubclasses(SimpleTestCase):
    def test_subclasses_generator(self):
        from django.db.models.query_utils import subclasses

        # Test that subclasses yields the class itself first
        results = list(subclasses(list))
        self.assertIn(list, results)

    def test_subclasses_recursive(self):
        from django.db.models.query_utils import subclasses

        # Test that subclasses recursively yields subclasses
        results = list(subclasses(list))
        self.assertIn(list, results)
        # Check that some subclasses are included (e.g., tuple is a subclass of object)
        self.assertIn(tuple, results)


class TestQClass(SimpleTestCase):
    def setUp(self):
        from django.db.models.query_utils import Q
        self.Q = Q

    def test_q_init_empty(self):
        q = self.Q()
        self.assertEqual(len(q.children), 0)

    def test_q_init_with_args(self):
        q = self.Q('field', 'value')
        # Q('field', 'value') creates 2 children from positional args
        self.assertEqual(len(q.children), 2)

    def test_q_init_with_kwargs(self):
        q = self.Q(field='value')
        self.assertEqual(len(q.children), 1)

    def test_q_init_with_connector(self):
        q = self.Q(_connector=self.Q.OR)
        self.assertEqual(q.connector, self.Q.OR)

    def test_q_init_with_negated(self):
        q = self.Q(_negated=True)
        self.assertTrue(q.negated)

    def test_q_or_operator(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        result = q1 | q2
        self.assertEqual(result.connector, self.Q.OR)

    def test_q_and_operator(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        result = q1 & q2
        self.assertEqual(result.connector, self.Q.AND)

    def test_q_invert_operator(self):
        q = self.Q(field='value')
        inverted = ~q
        self.assertTrue(inverted.negated)

    def test_q_combine_type_error(self):
        q = self.Q(field='value')
        with self.assertRaises(TypeError):
            q._combine("not a Q object", self.Q.AND)

    def test_q_combine_empty_other(self):
        q1 = self.Q(field='value')
        q2 = self.Q()
        result = q1._combine(q2, self.Q.AND)
        self.assertEqual(len(result.children), 1)

    def test_q_combine_empty_self(self):
        q1 = self.Q()
        q2 = self.Q(field='value')
        result = q1._combine(q2, self.Q.AND)
        self.assertEqual(len(result.children), 1)

    def test_q_deconstruct_single_child(self):
        q = self.Q(field='value')
        path, args, kwargs = q.deconstruct()
        self.assertIn('django.db.models', path)
        self.assertEqual(kwargs.get('field'), 'value')

    def test_q_deconstruct_multiple_children(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        combined = q1 & q2
        path, args, kwargs = combined.deconstruct()
        self.assertIn('django.db.models', path)
        self.assertEqual(len(args), 2)

    def test_q_deconstruct_custom_connector(self):
        q1 = self.Q(field1='value1')
        q2 = self.Q(field2='value2')
        combined = q1 | q2
        path, args, kwargs = combined.deconstruct()
        self.assertEqual(kwargs.get('_connector'), self.Q.OR)

    def test_q_deconstruct_negated(self):
        q = self.Q(field='value')
        negated = ~q
        path, args, kwargs = negated.deconstruct()
        self.assertTrue(kwargs.get('_negated'))


