        lookups = TestClass.get_lookups()
        self.assertIn('custom_lookup', lookups)

    def test_unregister_lookup(self):
        class Lookup:
            lookup_name = 'custom_lookup'

        class TestClass(self.Mixin):
            class_lookups = {'custom_lookup': Lookup}

        TestClass._unregister_lookup(Lookup)
        lookups = TestClass.get_lookups()
        self.assertNotIn('custom_lookup', lookups)


