        self.func = refs_expression

    def test_refs_expression_match_first_prefix(self):
        annotations = {'field': 'annotation_value'}
        result, remaining = self.func(['field', 'subfield'], annotations)
        self.assertEqual(result, 'annotation_value')
        self.assertEqual(remaining, ['subfield'])

    def test_refs_expression_match_full_path(self):
        annotations = {'field__subfield': 'annotation_value'}
        result, remaining = self.func(['field', 'subfield'], annotations)
        self.assertEqual(result, 'annotation_value')
        self.assertEqual(remaining, [])

    def test_refs_expression_no_match(self):
        annotations = {'other_field': 'annotation_value'}
        result, remaining = self.func(['field', 'subfield'], annotations)
        self.assertFalse(result)
        self.assertEqual(remaining, [])

    def test_refs_expression_empty_annotations(self):
        result, remaining = self.func(['field'], {})
        self.assertFalse(result)
        self.assertEqual(remaining, ())


