class TestFilteredRelation(SimpleTestCase):
    def setUp(self):
        from django.db.models.query_utils import FilteredRelation, Q
        self.FilteredRelation = FilteredRelation
        self.Q = Q

    def test_init_valid(self):
        fr = self.FilteredRelation('relation_name')
        self.assertEqual(fr.relation_name, 'relation_name')
        self.assertIsNone(fr.alias)
        self.assertIsInstance(fr.condition, self.Q)
        self.assertEqual(fr.path, [])

    def test_init_empty_relation_name_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.FilteredRelation('')

    def test_init_non_q_condition_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.FilteredRelation('relation_name', condition='not a Q')

    def test_eq_same_attributes(self):
        fr1 = self.FilteredRelation('relation_name', condition=self.Q(field='value'))
        fr2 = self.FilteredRelation('relation_name', condition=self.Q(field='value'))
        self.assertEqual(fr1, fr2)

    def test_eq_different_relation_name(self):
        fr1 = self.FilteredRelation('relation1', condition=self.Q())
        fr2 = self.FilteredRelation('relation2', condition=self.Q())
        self.assertNotEqual(fr1, fr2)

    def test_eq_different_alias(self):
        fr1 = self.FilteredRelation('relation_name', condition=self.Q())
        fr2 = self.FilteredRelation('relation_name', condition=self.Q())
        fr1.alias = 'alias1'
        fr2.alias = 'alias2'
        self.assertNotEqual(fr1, fr2)

    def test_eq_different_condition(self):
        fr1 = self.FilteredRelation('relation_name', condition=self.Q(field='value1'))
        fr2 = self.FilteredRelation('relation_name', condition=self.Q(field='value2'))
        self.assertNotEqual(fr1, fr2)

    def test_eq_different_class(self):
        fr1 = self.FilteredRelation('relation_name')
        fr2 = {'relation_name': 'relation_name'}
        self.assertNotEqual(fr1, fr2)

    def test_clone(self):
        fr = self.FilteredRelation('relation_name', condition=self.Q(field='value'))
        fr.alias = 'test_alias'
        fr.path = ['path1', 'path2']

        cloned = fr.clone()
        self.assertEqual(cloned.relation_name, 'relation_name')
        self.assertEqual(cloned.alias, 'test_alias')
        self.assertEqual(cloned.path, ['path1', 'path2'])

    def test_resolve_expression_raises_notimplementederror(self):
        fr = self.FilteredRelation('relation_name')
        with self.assertRaises(NotImplementedError):
            fr.resolve_expression()

