        from django.db.models.fields.related import RECURSIVE_RELATIONSHIP_CONSTANT, resolve_relation

        class Model(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test'

        result = resolve_relation(Model, RECURSIVE_RELATIONSHIP_CONSTANT)
        self.assertEqual(result, Model)

    def test_resolve_bare_model_name(self):
        from django.db.models.fields.related import resolve_relation

        class Model(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test'

        result = resolve_relation(Model, 'OtherModel')
        self.assertEqual(result, 'test.OtherModel')

    def test_resolve_qualified_model_name(self):
        from django.db.models.fields.related import resolve_relation

        class Model(models.Model):
            name = models.CharField(max_length=100)

            class Meta:
                app_label = 'test'

        result = resolve_relation(Model, 'other.OtherModel')
        self.assertEqual(result, 'other.OtherModel')

    def test_resolve_model_class(self):
        from django.db.models.fields.related import resolve_relation

