class ValidationErrorTests(SimpleTestCase):
    """Tests for ValidationError class."""

    def test_ValidationError_init_with_string_message(self):
        from django.core.exceptions import ValidationError
        error = ValidationError("Invalid value")
        self.assertEqual(error.message, "Invalid value")
        self.assertIsNone(error.code)
        self.assertIsNone(error.params)
        self.assertEqual(len(error.error_list), 1)

    def test_ValidationError_init_with_code(self):
        from django.core.exceptions import ValidationError
        error = ValidationError("Invalid value", code="invalid")
        self.assertEqual(error.message, "Invalid value")
        self.assertEqual(error.code, "invalid")
        self.assertIsNone(error.params)

    def test_ValidationError_init_with_params(self):
        from django.core.exceptions import ValidationError
        error = ValidationError("Value must be %s", params=("required",))
        self.assertEqual(error.message, "Value must be %s")
        self.assertEqual(error.params, ("required",))

    def test_ValidationError_init_with_all_args(self):
        from django.core.exceptions import ValidationError
        error = ValidationError("Invalid value", code="invalid", params=("value",))
        self.assertEqual(error.message, "Invalid value")
        self.assertEqual(error.code, "invalid")
        self.assertEqual(error.params, ("value",))

    def test_ValidationError_init_with_VerificationError_instance(self):
        from django.core.exceptions import ValidationError
        inner_error = ValidationError("Inner message")
        error = ValidationError(inner_error)
        self.assertEqual(error.message, "Inner message")

    def test_ValidationError_init_with_dict_message(self):
        from django.core.exceptions import ValidationError
        error = ValidationError({"field1": ["Error 1"], "field2": ["Error 2"]})
        self.assertTrue(hasattr(error, 'error_dict'))
        self.assertIn('field1', error.error_dict)
        self.assertIn('field2', error.error_dict)

    def test_ValidationError_init_with_list_message(self):
        from django.core.exceptions import ValidationError
        error = ValidationError(["Error 1", "Error 2"])
        self.assertTrue(hasattr(error, 'error_list'))
